-- A statement may be taken as of a date on or before the sheet's today: it goes by the sheet as it stood at the
-- end of that date, every change made while the sheet's today was on or after the next day left out. Each change
-- that moves a figure is therefore kept with the sheet's today when it was made (its made-on date); one already
-- there has none and counts as of every date.
ALTER TABLE statement ADD COLUMN as_of DATE;
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE sheet_setting_from ADD COLUMN made_on DATE;
-- Every rate set, in the order set, with the sheet's today then; the rate table keeps only the latest of each.
CREATE TABLE rate_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)   NOT NULL,
    from_date DATE,
    to_date   DATE,
    rate      DECIMAL(5, 2) NOT NULL,
    made_on   DATE         NOT NULL
);
CREATE INDEX rate_log_sheet ON rate_log (sheet_id, id);
-- A claim's binding log: one line each time a statement binds it to a figure (none when n/a) or leaves it
-- unbound, oldest first, with the sheet's today then. A claim already there has no log.
CREATE TABLE claim_binding_log (
    claim_id   BIGINT        NOT NULL REFERENCES claim (id),
    seq        INT           NOT NULL,
    on_date    DATE          NOT NULL,
    stated     BOOLEAN       NOT NULL,
    stated_due DECIMAL(12, 2),
    PRIMARY KEY (claim_id, seq)
);
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class StatementService {

    /** What a person's statements come to: how many, and the last one (none before the first). */
    public record Summary(int count, Statement last) {}

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final PersonRepository people;
    private final SheetService sheets;
    private final RollupService rollup;
    private final SettingService settings;
    private final Audit audit;

    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
            PersonRepository people, SheetService sheets, RollupService rollup, SettingService settings, Audit audit) {
        this.statements = statements;
        this.claims = claims;
        this.claimService = claimService;
        this.people = people;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, by person id. */
    @Transactional(readOnly = true)
    public Map<Long, Summary> summaries(String sheetId) {
        Map<Long, Summary> by = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
        }
        return by;
    }

    /**
     * Take a statement for a person: record their due-total now, late charges included and held to the cap, and bind each of their
     * claims that counts (OPEN and PENDING ones within a hold, unbound, and deferred ones do not) to the figure it has now (never its late charge, which keeps following the sheet's
     * today); a claim of theirs that does not count is left unbound.
     */
    @Transactional
    public Person take(String user, String sheetId, Long personId) {
        return take(user, sheetId, personId, null);
    }

    /**
     * Take a statement for a person as of a date on or before the sheet's today (none: now): as {@link #take}, but
     * by their claims that counted at the end of that date and their figures as they stood then (see
     * {@link RollupService#asOf}). A date after the sheet's today, or before the person was added, is refused.
     */
    @Transactional
    public Person take(String user, String sheetId, Long personId, LocalDate asOf) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (asOf != null && asOf.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A statement cannot be taken as of a date after the sheet's today.");
        }
        if (asOf != null && !person.addedBy(asOf)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    person.getName() + " was not on the sheet on " + asOf + ".");
        }
        Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonId(sheetId, personId);
        BigDecimal dueTotal;
        int counted;
        if (asOf != null) {
            RollupService.AsOf then = rollup.asOf(person, theirs, asOf);
            for (Claim claim : theirs) {
                if (then.figures().containsKey(claim.getId())) {
                    claim.bind(then.figures().get(claim.getId()), today);
                } else {
                    claim.unbind(today);
                }
            }
            dueTotal = then.dueTotal();
            counted = then.figures().size();
        } else {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            List<Claim> bound = new ArrayList<>();
            for (Claim claim : theirs) {
                if (!RollupService.counts(claim, person, today)) {
                    claim.unbind(today);
                    continue;
                }
                BigDecimal figure = claimService.figureOf(claim, person);
                BigDecimal due = rollup.dueOf(claim, person);
                fixed |= due != null;
                claim.bind(figure, today);
                bound.add(claim);
                if (due != null) {
                    total = total.add(due);
                }
            }
            // Like the screen: with no rate in force today and no claim having a figure, the due-total is n/a.
            boolean rated = rollup.rated(person, bound, today);
            dueTotal = rollup.capped(sheetId, rated || fixed ? total : null);
            counted = bound.size();
        }
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted, asOf));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
                + " claims=" + counted + (asOf != null ? " asof=" + asOf : ""));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /**
     * A steward cancels a person's last statement: it is removed, and the claims it bound are live again (a figure
     * bound by the statement before it is not restored). Refused for anyone else, and for a person with no statement.
     */
    @Transactional
    public Person cancel(String user, String sheetId, Long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        settings.requireSteward(sheetId, user);
        Statement last = statements.findFirstBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                        "That person has no statement to cancel."));
        LocalDate today = sheets.today(sheetId);
        Snapshot before = rollup.snapshot(sheetId);
        // Every claim of the person still bound was bound by their last statement, which rebinds or unbinds each.
        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
            if (claim.isStated()) {
                claim.unbind(today);
            }
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (last.getDueTotal() != null ? last.getDueTotal().toPlainString() : "n/a"));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Changing a sheet's today, and what follows from it. */
@Service
public class TodayService {

    private final SheetRepository sheets;
    private final SheetService sheetService;
    private final PeriodService periods;
    private final RollupService rollup;

    public TodayService(SheetRepository sheets, SheetService sheetService, PeriodService periods,
            RollupService rollup) {
        this.sheets = sheets;
        this.sheetService = sheetService;
        this.periods = periods;
        this.rollup = rollup;
    }

    /** Change the sheet's today; it writes no line of its own. Every open period past the sheet's grace days is
     * then closed, each writing its line, and then the figures the change moves are written. */
    @Transactional
    public Sheet setToday(String user, String id, LocalDate today) {
        sheetService.lock(id);
        Sheet sheet = sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        periods.closeLapsed(user, id);
        rollup.recordChanges(user, id, before);
        return sheet;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
public class SheetService {

    private final SheetRepository sheets;
    public SheetService(SheetRepository sheets) {
        this.sheets = sheets;
    }

    /** The sheet with this id, re-read from the store; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now()));
            } catch (DataIntegrityViolationException e) {
                // Another user created it at the same moment.
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /**
     * The sheet's today. Every feature that decides by the date, or defaults a date, asks this
     * rather than the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return find(id).getToday();
    }

    /**
     * Give out the sheet's next claim number. The sheet stays locked until the calling transaction
     * ends, so claims opened at the same moment get different numbers, and a rolled back
     * transaction gives its number back.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.incrementClaimNumber(id) == 0) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet.");
        }
        return sheets.lastClaimNumber(id);
    }

    /** Whether the sheet is archived, so that every change to it is refused. */
    @Transactional(readOnly = true)
    public boolean isArchived(String id) {
        return find(id).isArchived();
    }

    /** Whether a claim opened now on the sheet is numbered within its period, not sheet-wide. */
    @Transactional(readOnly = true)
    public boolean numbersByPeriod(String id) {
        return find(id).numbersByPeriod();
    }

    /** Lock the sheet until the calling transaction ends, so changes that must not race take turns. */
    @Transactional
    public void lock(String id) {
        sheets.findLocked(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }

    private Sheet find(String id) {
        return sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}

