            return;
        }
        if (read) {
            chain.doFilter(request, response);
            return;
        }
        transactions.executeWithoutResult(s -> history.keepFirst(sheetId));
        try {
            chain.doFilter(request, response);
        } finally {
            transactions.executeWithoutResult(s -> history.keep(sheetId));
        }
